pcall(function()
    if not (hookmetamethod and getnamecallmethod) then return end
    local cc = checkcaller or function() return false end
    local cap = remote("GuardService", "RF", "Capture")
    local old
    old = hookmetamethod(game, "__namecall", (newcclosure or function(f) return f end)(function(self, ...)
        if RUNNING and not cc() then
            if self == cap and on("eg_guard") and getnamecallmethod() == "InvokeServer" then
                return { Status = false, Reason = "" }
            end
            if self == MarketplaceService and on("pr_robux") then
                local m = getnamecallmethod()
                if type(m) == "string" and m:sub(1, 6) == "Prompt" then return nil end
            end
        end
        return old(self, ...)
    end))
    onClean(function() pcall(hookmetamethod, game, "__namecall", old) end)
end)
